mapper.select:
SELECT * FROM ( /* 1. 핫딜: TB_HOTDEAL_TRACKER + TB_PRICE_HISTORY 조인 */ SELECT t.DEAL_ID as "id", t.TITLE as "title", t.CURRENT_PRICE as "currentPrice", h.PRICE as "prevPrice", ROUND(((h.PRICE - t.CURRENT_PRICE) / h.PRICE) * 100, 1) as "dropRate", 'HOT' as "type" FROM TB_HOTDEAL_TRACKER t JOIN ( SELECT DEAL_ID, PRICE, ROW_NUMBER() OVER(PARTITION BY DEAL_ID ORDER BY RECORD_DATE DESC) as rn FROM TB_PRICE_HISTORY ) h ON t.DEAL_ID = h.DEAL_ID WHERE h.rn = 2 AND t.CURRENT_PRICE < h.PRICE
UNION ALL
/* 2. 일반 상품: Common_Product + PRICE_HISTORY 조인 */ SELECT p.PROD_ID as "id", p.PROD_NAME as "title", p.PROD_PRICE as "currentPrice", ph.PRICE as "prevPrice", ROUND(((ph.PRICE - p.PROD_PRICE) / ph.PRICE) * 100, 1) as "dropRate", 'NORMAL' as "type" FROM Common_Product p JOIN ( SELECT PROD_ID, PRICE, ROW_NUMBER() OVER(PARTITION BY PROD_ID ORDER BY REG_DATE DESC) as rn FROM PRICE_HISTORY ) ph ON p.PROD_ID = ph.PROD_ID WHERE ph.rn = 2 AND p.PROD_PRICE < ph.PRICE ) ORDER BY "dropRate" DESC OFFSET 0 ROWS FETCH NEXT 10 ROWS ONLY

SELECT * FROM ( /* 1. 핫딜 테이블에서 하락 상품 추출 */ SELECT t.DEAL_ID as "id", t.TITLE as "title", t.CURRENT_PRICE as "currentPrice", h.PRICE as "prevPrice", ROUND(((h.PRICE - t.CURRENT_PRICE) / h.PRICE) * 100, 1) as "dropRate", 'HOT' as "type" -- 구분을 위한 타입 FROM TB_HOTDEAL_TRACKER t JOIN ( SELECT DEAL_ID, PRICE, ROW_NUMBER() OVER(PARTITION BY DEAL_ID ORDER BY RECORD_DATE DESC) as rn FROM TB_PRICE_HISTORY ) h ON t.DEAL_ID = h.DEAL_ID WHERE h.rn = 2 AND t.CURRENT_PRICE < h.PRICE
UNION ALL
/* 2. 일반 상품 테이블에서 하락 상품 추출 */ SELECT p.PROD_ID as "id", p.PROD_NAME as "title", p.PROD_PRICE as "currentPrice", ph.PRICE as "prevPrice", ROUND(((ph.PRICE - p.PROD_PRICE) / ph.PRICE) * 100, 1) as "dropRate", 'NORMAL' as "type" FROM Common_Product p JOIN ( SELECT PROD_ID, PRICE, ROW_NUMBER() OVER(PARTITION BY PROD_ID ORDER BY REG_DATE DESC) as rn FROM PRICE_HISTORY ) ph ON p.PROD_ID = ph.PROD_ID WHERE ph.rn = 2 AND p.PROD_PRICE < ph.PRICE
) ORDER BY "dropRate" DESC -- 전체 결과 중 하락율이 높은 순으로 정렬 OFFSET 0 ROWS FETCH NEXT 10 ROWS ONLY -- 상위 10개만
